package tryon

import (
	"context"
	"errors"
	"strconv"
	"time"

	"github.com/gogf/gf/v2/errors/gcode"
	"github.com/gogf/gf/v2/errors/gerror"
	"github.com/gogf/gf/v2/net/ghttp"

	"backend/api/tryon/v1"
	"backend/internal/imagevalidate"
	"backend/internal/logic/tryon"
	"backend/internal/middleware"
	"backend/internal/security"
)

type ControllerV1 struct{}

// ConcurrencyRetryAfterSeconds 并发已满（含排队超时）时建议客户端的重试间隔。
const ConcurrencyRetryAfterSeconds = 5

func NewV1() *ControllerV1 {
	return &ControllerV1{}
}

func (c *ControllerV1) Tryon(ctx context.Context, req *v1.TryonReq) (res *v1.TryonRes, err error) {
	r := ghttp.RequestFromCtx(ctx)
	secService := security.GetService()
	imgLimits := imagevalidate.LoadImageLimits(ctx)

	// 1. 严格校验两张图片（人像和服装）真实格式、文件大小、尺寸及像素
	personImg, garmentImg, imgErr := imagevalidate.ValidateImagesPair(req.PersonImage, req.GarmentImage, imgLimits)
	if imgErr != nil {
		if apiErr, ok := imgErr.(*security.APIError); ok {
			middleware.WriteAPIError(r, apiErr)
			return nil, nil
		}
		middleware.WriteAPIError(r, security.ErrInvalidImageBase64)
		return nil, nil
	}

	principalID := r.GetCtxVar(middleware.CtxPrincipalID).String()
	if principalID == "" {
		principalID = "anonymous"
	}

	// 2. 先占用并发槽位：被并发限制拒绝的请求不应消耗每日额度。
	//    全局已满时按 security.concurrency.queueTimeoutSeconds 短暂排队（客户端断开即放弃）。
	queueWait := time.Duration(secService.Config.Concurrency.QueueTimeoutSeconds) * time.Second
	release, ok := secService.ConcurrencyManager.AcquireWait(ctx, principalID, queueWait)
	if !ok {
		r.Response.Header().Set("Retry-After", strconv.Itoa(ConcurrencyRetryAfterSeconds))
		middleware.WriteAPIError(r, security.ErrConcurrencyLimited)
		return nil, nil
	}
	defer release()

	// 3. 检查并原子扣减每日调用额度
	if !secService.DailyQuotaTracker.CheckAndDeduct(principalID) {
		middleware.WriteAPIError(r, security.ErrDailyQuotaExceeded)
		return nil, nil
	}

	var clientConfig *tryon.ModelConfig
	if req.ClientConfig != nil {
		clientConfig = &tryon.ModelConfig{
			Name:     "browser-custom",
			Provider: req.ClientConfig.Provider,
			APIKey:   req.ClientConfig.APIKey,
			BaseURL:  req.ClientConfig.BaseURL,
			Model:    req.ClientConfig.Model,
		}
	}

	imageB64, model, prompt, err := tryon.DoTryonWithValidatedImages(
		ctx,
		personImg,
		garmentImg,
		req.Model,
		req.Size,
		req.Lang,
		clientConfig,
	)
	if err != nil {
		// 参数/模型配置错误发生在调用上游之前，没有产生成本，退还额度
		if !errors.Is(err, security.ErrUpstreamFailed) && gerror.Code(err) == gcode.CodeInvalidParameter {
			secService.DailyQuotaTracker.Refund(principalID)
		}
		return nil, err
	}
	imageMIME, err := tryon.DetectGeneratedImageMIME(imageB64)
	if err != nil {
		// 上游返回了非图片内容：按上游失败处理，不回显内容
		return nil, security.ErrUpstreamFailed
	}
	return &v1.TryonRes{
		Image:  imageB64,
		MIME:   imageMIME,
		Model:  model,
		Prompt: prompt,
	}, nil
}

func (c *ControllerV1) ComfyUIHealth(ctx context.Context, req *v1.ComfyUIHealthReq) (res *v1.ComfyUIHealthRes, err error) {
	model, healthErr := tryon.CheckComfyUI(ctx)
	if healthErr != nil {
		return &v1.ComfyUIHealthRes{
			Available: false,
			Message:   "本地 ComfyUI 或固定工作流不可用",
		}, nil
	}
	return &v1.ComfyUIHealthRes{
		Available: true,
		Model:     model,
		Message:   "本地 ComfyUI 固定工作流可用",
	}, nil
}
